From 0c3cd7a0b862c37acbee6d9502107146cc944398 Mon Sep 17 00:00:00 2001
From: Jia-Hong Su <s11242586@gmail.com>
Date: Sun, 18 Jan 2026 20:08:59 +0800
Subject: [PATCH] Bluetooth: hci_uart: fix null-ptr-deref in
 hci_uart_write_work

hci_uart_set_proto() sets HCI_UART_PROTO_INIT before calling
hci_uart_register_dev(), which calls proto->open() to initialize
hu->priv. However, if a TTY write wakeup occurs during this window,
hci_uart_tx_wakeup() may schedule write_work before hu->priv is
initialized, leading to a NULL pointer dereference in
hci_uart_write_work() when proto->dequeue() accesses hu->priv.

The race condition is:

  CPU0                              CPU1

diff --git a/drivers/bluetooth/hci_ldisc.c b/drivers/bluetooth/hci_ldisc.c
index d0adae3267b4..2b28515de92c 100644
--- a/drivers/bluetooth/hci_ldisc.c
+++ b/drivers/bluetooth/hci_ldisc.c
@@ -685,6 +685,8 @@ static int hci_uart_register_dev(struct hci_uart *hu)
 		return err;
 	}

+	set_bit(HCI_UART_PROTO_INIT, &hu->flags);
+
 	if (test_bit(HCI_UART_INIT_PENDING, &hu->hdev_flags))
 		return 0;

@@ -712,8 +714,6 @@ static int hci_uart_set_proto(struct hci_uart *hu, int id)

 	hu->proto = p;

-	set_bit(HCI_UART_PROTO_INIT, &hu->flags);
-
 	err = hci_uart_register_dev(hu);
 	if (err) {
 		return err;
-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Bluetooth: hci_uart: fix null-ptr-deref in
 hci_uart_write_work

hci_uart_set_proto() sets HCI_UART_PROTO_INIT before calling
hci_uart_register_dev(), which calls proto->open() to initialize
hu->priv. However, if a TTY write wakeup occurs during this window,
hci_uart_tx_wakeup() may schedule write_work before hu->priv is
initialized, leading to a NULL pointer dereference in
hci_uart_write_work() when proto->dequeue() accesses hu->priv.

The race condition is:

  CPU0                              CPU1
  ----                              ----
  hci_uart_set_proto()
    set_bit(HCI_UART_PROTO_INIT)
    hci_uart_register_dev()
                                    tty write wakeup
                                      hci_uart_tty_wakeup()
                                        hci_uart_tx_wakeup()
                                          schedule_work(&hu->write_work)
      proto->open(hu)
        // initializes hu->priv
                                    hci_uart_write_work()
                                      hci_uart_dequeue()
                                        proto->dequeue(hu)
                                          // accesses hu->priv (NULL!)

Fix this by moving set_bit(HCI_UART_PROTO_INIT) after proto->open()
succeeds, ensuring hu->priv is initialized before any work can be
scheduled.

Fixes: 5df5dafc171b ("Bluetooth: hci_uart: Fix another race during initialization")
Link: https://lore.kernel.org/linux-bluetooth/6969764f.170a0220.2b9fc4.35a7@mx.google.com/

Signed-off-by: Jia-Hong Su <s11242586@gmail.com>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
The HCI_UART_PROTO_INIT flag was set in hci_uart_set_proto() before calling hci_uart_register_dev() which initializes hu->priv via proto->open(). This allows a race condition where a TTY write wakeup can schedule hci_uart_write_work() before hu->priv is initialized, leading to a null pointer dereference when proto->dequeue() accesses hu->priv.

Here is the patch:

 static int hci_uart_register_dev(struct hci_uart *hu)
 {
 	struct hci_dev *hdev;
 	int err;

 	BT_DBG("");

 	/* Initialize and register HCI device */
 	hdev = hci_alloc_dev();
 	if (!hdev) {
 		BT_ERR("Can't allocate HCI device");
 		return -ENOMEM;
 	}

 	hu->hdev = hdev;

 	hdev->bus = HCI_UART;
 	hci_set_drvdata(hdev, hu);

 	/* Only when vendor specific setup callback is provided, consider
 	 * the manufacturer information valid. This avoids filling in the
 	 * value for Ericsson when nothing is specified.
 	 */
 	if (hu->proto->setup)
 		hdev->manufacturer = hu->proto->manufacturer;

 	hdev->open  = hci_uart_open;
 	hdev->close = hci_uart_close;
 	hdev->flush = hci_uart_flush;
 	hdev->send  = hci_uart_send_frame;
 	hdev->setup = hci_uart_setup;
 	SET_HCIDEV_DEV(hdev, hu->tty->dev);

 	if (test_bit(HCI_UART_RAW_DEVICE, &hu->hdev_flags))
 		hci_set_quirk(hdev, HCI_QUIRK_RAW_DEVICE);

 	if (test_bit(HCI_UART_EXT_CONFIG, &hu->hdev_flags))
 		hci_set_quirk(hdev, HCI_QUIRK_EXTERNAL_CONFIG);

 	if (!test_bit(HCI_UART_RESET_ON_INIT, &hu->hdev_flags))
 		hci_set_quirk(hdev, HCI_QUIRK_RESET_ON_CLOSE);

 	/* Only call open() for the protocol after hdev is fully initialized as
 	 * open() (or a timer/workqueue it starts) may attempt to reference it.
 	 */
 	err = hu->proto->open(hu);
 	if (err) {
 		hu->hdev = NULL;
 		hci_free_dev(hdev);
 		return err;
 	}

+	set_bit(HCI_UART_PROTO_INIT, &hu->flags);
+
 	if (test_bit(HCI_UART_INIT_PENDING, &hu->hdev_flags))
 		return 0;

 	if (hci_register_dev(hdev) < 0) {
 		BT_ERR("Can't register HCI device");
 		hu->proto->close(hu);
 		hu->hdev = NULL;
 		hci_free_dev(hdev);
 		return -ENODEV;
 	}

 	set_bit(HCI_UART_REGISTERED, &hu->flags);

 	return 0;
 }

 static int hci_uart_set_proto(struct hci_uart *hu, int id)
 {
 	const struct hci_uart_proto *p;
 	int err;

 	p = hci_uart_get_proto(id);
 	if (!p)
 		return -EPROTONOSUPPORT;

 	hu->proto = p;

-	set_bit(HCI_UART_PROTO_INIT, &hu->flags);
-
 	err = hci_uart_register_dev(hu);
 	if (err) {
 		return err;
 	}

 	set_bit(HCI_UART_PROTO_READY, &hu->flags);
 	clear_bit(HCI_UART_PROTO_INIT, &hu->flags);

 	return 0;
 }



